// The set of URLs a standard-build (Next.js + Keystatic) client serves,
// enumerated from committed source so it cannot drift from what ships, and
// without needing a server. Two checks share it: doorway-ratio (denominator,
// when no server is available) and redirect-chains ("does this redirect land
// somewhere real?" — the question a wildcard rule can only answer against the
// served set; 51 legacy URLs redirected into a 404 for four days before it
// was asked).
//
// Conventions of the standard build, every one optional:
//   src/app/**/page.tsx          static routes (route groups stripped, dynamic segments skipped);
//                                a page whose metadata says `index: false` is served but unlisted
//   src/lib/local-seo-data.ts    city hubs ({ slug, parentSlug }) under /locations/<state>
//   content/practice-areas/<slug>/index.mdoc, content/case-types/<parent>/<child>.json,
//   content/posts/<slug>/index.mdoc (+ categories frontmatter → /blog/category/<c>),
//   content/faq-pages/<slug>.yaml, content/es/{posts,locations,practice-areas,guides}/<slug>.json
import fs from 'node:fs';
import path from 'node:path';

const STATE_PATH = { GA: 'georgia', SC: 'south-carolina', FL: 'florida', NC: 'north-carolina', AL: 'alabama', TN: 'tennessee' };

const list = (repo, p, kind) => {
  const full = path.join(repo, p);
  if (!fs.existsSync(full)) return [];
  return fs.readdirSync(full, { withFileTypes: true })
    .filter(e => kind === 'dir' ? e.isDirectory() : e.name.endsWith(kind))
    .map(e => kind === 'dir' ? e.name : e.name.slice(0, -kind.length))
    .filter(s => !/\s\d+$/.test(s)); // Google Drive conflict dupes
};

function walkPages(dir, rel, out) {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (e.name.startsWith('_') || e.name.startsWith('@')) continue;
      const seg = /^\(.*\)$/.test(e.name) ? '' : '/' + e.name;
      walkPages(path.join(dir, e.name), rel + seg, out);
    } else if (/^page\.(tsx|jsx|ts|js|mdx)$/.test(e.name)) out.push({ route: rel || '/', file: path.join(dir, e.name) });
  }
  return out;
}

/** Static app-router routes: { url, unlisted } — unlisted when the page declares robots noindex. */
export function listStaticRoutes(repo) {
  return walkPages(path.join(repo, 'src', 'app'), '', [])
    .filter(p => !/\[[^\]]+\]/.test(p.route))
    .map(p => ({ url: p.route, unlisted: /index:\s*false/.test(fs.readFileSync(p.file, 'utf8')) }))
    .sort((a, b) => a.url.localeCompare(b.url));
}

/**
 * Every URL the app serves, as { url, geo, unlisted }.
 * @param {string} repo absolute repo root
 * @param {{ classify: (slug: string) => { isGeo: boolean }, states?: string[], locationsPrefix?: string, includeUnlisted?: boolean }} opts
 */
export function listSiteUrls(repo, opts = {}) {
  const isGeo = (slug) => opts.classify ? opts.classify(slug).isGeo : false;
  const urls = [];
  const seen = new Set();
  const add = (url, geo, unlisted = false) => { if (!seen.has(url)) { seen.add(url); urls.push({ url, geo, unlisted }); } };

  for (const r of listStaticRoutes(repo)) add(r.url, r.url.startsWith('/locations/'), r.unlisted);
  // The Spanish blog index is served but left out of the sitemap while it has no
  // posts (every /es/blog entry a cull retires takes its twin with it).
  if (seen.has('/es/blog') && !list(repo, 'content/es/posts', '.json').length) urls.find(u => u.url === '/es/blog').unlisted = true;

  const state = (opts.states || ['GA'])[0];
  const prefix = opts.locationsPrefix || `/locations/${STATE_PATH[state] || state.toLowerCase()}`;
  const localSeo = path.join(repo, 'src/lib/local-seo-data.ts');
  if (fs.existsSync(localSeo)) {
    add(prefix, true);
    for (const block of fs.readFileSync(localSeo, 'utf8').split(/\n  \{/).slice(1)) {
      const slug = block.match(/^\s*slug: '([^']+)'/m)?.[1];
      if (!slug) continue;
      const parent = block.match(/^\s*parentSlug: '([^']+)'/m)?.[1];
      add(parent ? `${prefix}/${parent}/${slug}` : `${prefix}/${slug}`, true);
    }
  }
  list(repo, 'content/practice-areas', 'dir').forEach(s => add(`/practice-areas/${s}`, isGeo(s)));
  for (const parent of list(repo, 'content/case-types', 'dir')) {
    for (const child of list(repo, `content/case-types/${parent}`, '.json')) add(`/practice-areas/${parent}/${child}`, isGeo(child));
  }
  list(repo, 'content/posts', 'dir').forEach(s => add(`/blog/${s}`, isGeo(s)));
  listCategoryUrls(repo).forEach(u => add(u, isGeo(u.split('/').pop())));
  list(repo, 'content/faq-pages', '.yaml').forEach(s => add(`/faqs/${s}`, false));
  list(repo, 'content/faq-pages', '.yml').forEach(s => add(`/faqs/${s}`, false));
  list(repo, 'content/es/posts', '.json').forEach(s => add(`/es/blog/${s}`, isGeo(s)));
  list(repo, 'content/es/locations', '.json').forEach(s => add(`/es/ubicaciones/${s}`, true));
  list(repo, 'content/es/practice-areas', '.json').forEach(s => add(`/es/${s}`, false));
  list(repo, 'content/es/guides', '.json').forEach(s => add(`/es/guias/${s}`, false));

  return opts.includeUnlisted ? urls : urls.filter(u => !u.unlisted);
}

/** Blog category archive URLs, derived from the `categories` frontmatter the category route reads. */
export function listCategoryUrls(repo) {
  const cats = new Set();
  for (const slug of list(repo, 'content/posts', 'dir')) {
    const f = path.join(repo, 'content/posts', slug, 'index.mdoc');
    if (!fs.existsSync(f)) continue;
    const m = fs.readFileSync(f, 'utf8').match(/^categories:\s*\[(.*)\]/m);
    if (m) for (const c of m[1].matchAll(/"([^"]+)"|'([^']+)'/g)) cats.add(c[1] || c[2]);
  }
  return [...cats].map(c => `/blog/category/${c}`);
}
